#!/usr/bin/env python3
"""Minimal VT100/xterm screen parser. Feed raw bytes, get final screen text.
Usage: from vtparse import Screen; s=Screen(rows,cols); s.feed(data); print(s.render())
"""
import re

class Screen:
    def __init__(self, rows=24, cols=80):
        self.rows = rows
        self.cols = cols
        self.grid = [[" "] * cols for _ in range(rows)]
        self.r = 0
        self.c = 0
        self.saved = (0, 0)

    def feed(self, data):
        if isinstance(data, bytes):
            data = data.decode("utf-8", "replace")
        i = 0
        n = len(data)
        while i < n:
            ch = data[i]
            if ch == "\x1b":
                m = re.match(r"\x1b\[([0-9;?]*)([A-Za-z@`~])", data[i:])
                if m:
                    params, cmd = m.group(1), m.group(2)
                    self._csi(params, cmd)
                    i += m.end()
                    continue
                m = re.match(r"\x1b\][^\x07\x1b]*(\x07|\x1b\\)", data[i:])
                if m:  # OSC
                    i += m.end()
                    continue
                m = re.match(r"\x1b[=><()#].?", data[i:])
                if m:
                    i += m.end()
                    continue
                m = re.match(r"\x1b[HM78c]", data[i:])
                if m:
                    if m.group(0) == "\x1b7":
                        self.saved = (self.r, self.c)
                    elif m.group(0) == "\x1b8":
                        self.r, self.c = self.saved
                    elif m.group(0) == "\x1bM":
                        self.r = max(0, self.r - 1)
                    i += m.end()
                    continue
                i += 1
                continue
            if ch == "\r":
                self.c = 0
            elif ch == "\n":
                self.r = min(self.rows - 1, self.r + 1)
            elif ch == "\b":
                self.c = max(0, self.c - 1)
            elif ch == "\t":
                self.c = min(self.cols - 1, (self.c // 8 + 1) * 8)
            elif ch >= " ":
                if 0 <= self.r < self.rows and 0 <= self.c < self.cols:
                    self.grid[self.r][self.c] = ch
                self.c += 1
                if self.c >= self.cols:
                    self.c = self.cols - 1
            i += 1

    def _csi(self, params, cmd):
        priv = params.startswith("?")
        p = params.lstrip("?")
        nums = [int(x) if x else 0 for x in p.split(";")] if p else []
        def arg(idx, default):
            return nums[idx] if idx < len(nums) and nums[idx] != 0 else default
        if cmd == "H" or cmd == "f":
            self.r = min(self.rows - 1, arg(0, 1) - 1)
            self.c = min(self.cols - 1, arg(1, 1) - 1)
        elif cmd == "A":
            self.r = max(0, self.r - arg(0, 1))
        elif cmd == "B":
            self.r = min(self.rows - 1, self.r + arg(0, 1))
        elif cmd == "C":
            self.c = min(self.cols - 1, self.c + arg(0, 1))
        elif cmd == "D":
            self.c = max(0, self.c - arg(0, 1))
        elif cmd == "G" or cmd == "`":
            self.c = min(self.cols - 1, arg(0, 1) - 1)
        elif cmd == "d":
            self.r = min(self.rows - 1, arg(0, 1) - 1)
        elif cmd == "J":
            mode = arg(0, 0) if nums else 0
            if mode == 2 or mode == 3:
                self.grid = [[" "] * self.cols for _ in range(self.rows)]
            elif mode == 0:
                for cc in range(self.c, self.cols):
                    self.grid[self.r][cc] = " "
                for rr in range(self.r + 1, self.rows):
                    self.grid[rr] = [" "] * self.cols
        elif cmd == "K":
            mode = arg(0, 0) if nums else 0
            if mode == 0:
                for cc in range(self.c, self.cols):
                    self.grid[self.r][cc] = " "
            elif mode == 2:
                self.grid[self.r] = [" "] * self.cols
        elif cmd == "s":
            self.saved = (self.r, self.c)
        elif cmd == "u":
            self.r, self.c = self.saved

    def render(self):
        return "\n".join("".join(row).rstrip() for row in self.grid)

if __name__ == "__main__":
    import sys
    data = open(sys.argv[1], "rb").read() if len(sys.argv) > 1 else sys.stdin.buffer.read()
    rows = int(sys.argv[2]) if len(sys.argv) > 2 else 24
    cols = int(sys.argv[3]) if len(sys.argv) > 3 else 80
    s = Screen(rows, cols)
    s.feed(data)
    print(s.render())

